function Assert-Exp123CollectorLifecycle([string]$Root){$p=Join-Path $Root 'pool/collector-lifecycle.json';if(-not(Test-Path $p)){throw 'Collector lifecycle artifact missing'};$l=Get-Content $p -Raw|ConvertFrom-Json;if($l.mode-ne'CORE_BOUND_STOP_SIGNAL'-or$l.lifecycleStatus-ne'COLLECTOR_LIFECYCLE_PASSED'-or$l.stopSignalObserved-ne$true-or$l.processExitCode-ne0){throw 'Collector lifecycle contract failed'};if([DateTimeOffset]::Parse($l.collectorFirstSampleCoveringCoreEndAt)-lt[DateTimeOffset]::Parse($l.coreInvocationCompletedAt)){throw 'Post-core coverage failed'}}
function Set-Exp123Terminal([string]$Root,[ValidateSet('COMPLETED','EXECUTION_FAILED')][string]$State){Remove-Item (Join-Path $Root 'RUNNING') -Force -ErrorAction SilentlyContinue;Remove-Item (Join-Path $Root 'COMPLETED') -Force -ErrorAction SilentlyContinue;Remove-Item (Join-Path $Root 'EXECUTION_FAILED') -Force -ErrorAction SilentlyContinue;New-Item -ItemType File -Path (Join-Path $Root $State)|Out-Null}
